input.sparql:
PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?point ?timeseries_id WHERE {
  ?zone a brick:Zone ;
    rdfs:label 'Core_top' ;
    brick:hasPoint/brick:isSensorOf brick:Lighting_Power .
  ?point rdfs:label ?label ;
    ref：hasExternalReference/ref：hasTimeseriesId ?timeseries_id .
}
